use crate::claude_code::ClaudeCode;
use crate::db::Database;
use anyhow::anyhow;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use tokio::time::{Duration, sleep};
use tracing::{error, info, warn};

/// Manages per-chat style profiles generated by LLM analysis of conversation history.
pub struct ChatProfileManager {
    db: Database,
    cache: RwLock<HashMap<i64, String>>, // chat_id -> prompt_instruction
    claude: Arc<ClaudeCode>,
}

impl ChatProfileManager {
    pub fn new(
        db: Database,
        claude: Arc<ClaudeCode>,
    ) -> Self {
        Self {
            db,
            cache: RwLock::new(HashMap::new()),
            claude,
        }
    }

    /// Get the cached style instruction for a chat, falling back to DB.
    pub async fn get_profile(&self, chat_id: i64) -> Option<String> {
        // Fast path: check in-memory cache
        {
            let cache = self.cache.read().await;
            if let Some(instruction) = cache.get(&chat_id) {
                return Some(instruction.clone());
            }
        }

        // Cache miss: check DB
        match self.db.get_chat_profile(chat_id).await {
            Ok(Some((instruction, _json, _count))) => {
                let mut cache = self.cache.write().await;
                cache.insert(chat_id, instruction.clone());
                Some(instruction)
            }
            Ok(None) => None,
            Err(e) => {
                warn!(?e, chat_id, "failed to load chat profile from DB");
                None
            }
        }
    }

    /// Background loop: periodically find chats needing profiles and generate them.
    pub async fn run_background(&self) {
        info!("chat profile manager started (checking every 5 min)");
        loop {
            sleep(Duration::from_secs(300)).await;
            if let Err(e) = self.check_and_generate().await {
                error!(?e, "chat profile check failed");
            }
        }
    }

    async fn check_and_generate(&self) -> anyhow::Result<()> {
        let chats = self.db.get_chats_needing_profile(30, 100).await?;
        if chats.is_empty() {
            return Ok(());
        }
        info!(count = chats.len(), "chats needing profile analysis");

        for (chat_id, title, msg_count) in chats {
            match self.analyze_chat(chat_id, &title, msg_count).await {
                Ok(()) => info!(chat_id, %title, "chat profile generated"),
                Err(e) => warn!(?e, chat_id, %title, "failed to generate chat profile"),
            }
            // Pause between analyses to avoid CLI overload
            sleep(Duration::from_secs(3)).await;
        }
        Ok(())
    }

    async fn analyze_chat(
        &self,
        chat_id: i64,
        title: &str,
        msg_count: i64,
    ) -> anyhow::Result<()> {
        let messages = self
            .db
            .fetch_recent_chat_messages_with_names(chat_id, None, 80)
            .await?;

        if messages.is_empty() {
            return Ok(());
        }

        // Format conversation lines
        let mut formatted = String::new();
        for (_sender_id, sender_name, content, _created_at) in &messages {
            let name = sender_name.as_deref().unwrap_or("Unknown");
            formatted.push_str(&format!("{}: {}\n", name, content));
        }

        let kind = "group";

        let system = "Sen chat uslubi tahlilchisi. Berilgan Telegram chat xabarlarini tahlil qilib, chatning muloqot uslubini aniqlaysan. Javob faqat JSON formatida bo'lsin. MUHIM: bot_send_message ISHLATMA. Hech qanday tool chaqirma. Faqat JSON matnini javob sifatida qaytar.";

        let user_prompt = format!(
            r#"Chat: "{title}" (turi: {kind})

Xabarlar:
{formatted}
Tahlil qilib, quyidagi JSON formatda javob ber:
{{
  "formality": "formal|casual|mixed",
  "language_mix": "pure_uzbek|uz_ru_mix|uz_en_mix|multilingual",
  "slang_expressions": ["chatda ishlatiladigan slang va iboralar"],
  "humor_style": "none|light|heavy|sarcastic",
  "typical_topics": ["asosiy mavzular"],
  "address_style": "siz|sen|mixed",
  "emoji_usage": "none|rare|moderate|heavy",
  "instruction": "Jarvis uchun 2-3 jumlalik ko'rsatma: bu chatda qanday ohangda, qanday so'zlar bilan gaplashish kerak. Chatdagi odamlar qanday gaplashsa, Jarvis ham o'sha uslubda moslashsin. Aniq misollar bilan yoz."
}}

MUHIM: Faqat JSON qaytar, boshqa hech narsa yozma. HECH QANDAY tool (bot_send_message, send_reaction va h.k.) ISHLATMA — faqat JSON matnini text sifatida qaytar. "instruction" eng muhim — Jarvisga bu chatda qanday gaplashishni aniq ko'rsatsin."#
        );

        let combined_prompt = format!(
            "[System: {}]\n\n{}",
            system, user_prompt,
        );
        let response = self.claude.send_message(&combined_prompt, "Analyzing chat style").await?;

        // Extract JSON from response (may have markdown fences)
        let json_str = extract_json(&response)
            .ok_or_else(|| anyhow!("no JSON found in profile response"))?;

        // Parse and extract instruction
        let parsed: serde_json::Value = serde_json::from_str(json_str)
            .map_err(|e| anyhow!("failed to parse profile JSON: {e}"))?;

        let instruction = parsed
            .get("instruction")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow!("no 'instruction' field in profile JSON"))?
            .to_string();

        // Store in DB
        self.db
            .upsert_chat_profile(chat_id, json_str, &instruction, msg_count)
            .await?;

        // Update cache
        {
            let mut cache = self.cache.write().await;
            cache.insert(chat_id, instruction);
        }

        Ok(())
    }
}

/// Extract the first JSON object from a string that may contain markdown fences.
fn extract_json(s: &str) -> Option<&str> {
    if let Some(start) = s.find("```json") {
        let after = &s[start + 7..];
        if let Some(end) = after.find("```") {
            return Some(after[..end].trim());
        }
    }
    if let Some(start) = s.find("```") {
        let after = &s[start + 3..];
        let after = if let Some(nl) = after.find('\n') {
            &after[nl + 1..]
        } else {
            after
        };
        if let Some(end) = after.find("```") {
            return Some(after[..end].trim());
        }
    }
    // Raw JSON: find first { and last }
    let start = s.find('{')?;
    let end = s.rfind('}')?;
    if end > start {
        Some(&s[start..=end])
    } else {
        None
    }
}
